// The "What you get" section's vectors, exported from the Figma slides (7068:30959 Works for everyone, 7071:31173
// Nothing hardcoded, 7071:31734 Your icons) and drawn in currentColor, so CSS gives them Icon/icon-brand. Phosphor's
// token icons keep Figma's export as is; the accessibility figure and the icon grid are rebuilt as strokes so
// they can move (Figma annotations: "animate this as the hands and legs spread out", "animate as you're drawing
// this"), and the eye is one eye that blinks ("this should be a blinking eye", the closed one is Figma's).
import type { CSSProperties, ReactNode, SVGProps } from 'react';

type Props = SVGProps<SVGSVGElement>;

const stroke = (w: number) => ({
  stroke: 'currentColor',
  strokeWidth: w,
  strokeLinecap: 'round' as const,
  strokeLinejoin: 'round' as const,
  fill: 'none',
});

/** Phosphor icons at Figma's 52 (stroke 3.9), each as its own small SVG. */
function Icon52({ children, ...rest }: Props & { children: ReactNode }) {
  return (
    <svg width="52" height="52" viewBox="0 0 52 52" aria-hidden {...rest}>
      <g {...stroke(3.9)}>{children}</g>
    </svg>
  );
}

