/**
 * The icon grid (Figma "Magnified Preview" 7071:32182, 200): Phosphor's keyline grid with an icon on it. Every line
 * is its own stroke with pathLength 1, so CSS draws it from nothing (stroke-dashoffset): the pixel grid first, then
 * the keylines, then the icon's frame and its crosshair. Figma's icon is one filled shape; here it is drawn as the
 * strokes it is made of.
 */
export function IconGrid(p: Props) {
  const minor = Array.from({ length: 23 }, (_, k) => (k + 1) * 8.3333);
  let g = 0;
  const line = (d: string, extra?: object) => (
    <path key={g} d={d} pathLength={1} className="wyg-grid__line" style={{ '--g': g++ } as CSSProperties} {...extra} />
  );
  return (
    <svg className="wyg-grid" width="200" height="200" viewBox="0 0 200 200" aria-hidden {...p}>
      <path className="wyg-grid__frame" fillRule="evenodd" d="M200 0H0V200H200V0ZM183.333 16.6667H16.6667V183.333H183.333V16.6667Z" fill="currentColor" fillOpacity={0.1} />
      <g className="wyg-grid__minor" stroke="currentColor" strokeOpacity={0.1} strokeWidth="1.08333" fill="none">
        {minor.map((v) => line(`M${v} 0V200`))}
        {minor.map((v) => line(`M0 ${v}H200`))}
      </g>
      <g className="wyg-grid__keys" stroke="currentColor" strokeWidth="0.520833" fill="none">
        {line('M66.666 0V200')}
        {line('M133.334 0V200')}
        {line('M0 66.6665H200')}
        {line('M0 133.333H200')}
        {line('M0 0L200 200')}
        {line('M0 200L200 0')}
        {line('M41.667 25H158.333A16.667 16.667 0 0 1 175 41.667V158.333A16.667 16.667 0 0 1 158.333 175H41.667A16.667 16.667 0 0 1 25 158.333V41.667A16.667 16.667 0 0 1 41.667 25Z')}
        {line('M50 16.667H150A16.667 16.667 0 0 1 166.667 33.333V166.667A16.667 16.667 0 0 1 150 183.333H50A16.667 16.667 0 0 1 33.333 166.667V33.333A16.667 16.667 0 0 1 50 16.667Z')}
        {line('M33.333 33.333H166.667A16.667 16.667 0 0 1 183.333 50V150A16.667 16.667 0 0 1 166.667 166.667H33.333A16.667 16.667 0 0 1 16.667 150V50A16.667 16.667 0 0 1 33.333 33.333Z')}
        {line('M100 16.667A83.333 83.333 0 1 1 100 183.333A83.333 83.333 0 1 1 100 16.667Z')}
        {line('M100 66.667A33.333 33.333 0 1 1 100 133.333A33.333 33.333 0 1 1 100 66.667Z')}
        {line('M0.26 0.26H199.74V199.74H0.26Z')}
      </g>
      <g className="wyg-grid__icon" stroke="currentColor" fill="none">
        {line('M55.834 75H144.405V125H55.834Z', { strokeWidth: 5.714, strokeLinejoin: 'miter' })}
        <g className="wyg-grid__cross" strokeWidth="2.857" strokeDasharray="5.63 8.27">
          <path d="M100 0V58.333M100 141.667V200" />
          <path d="M0 100.119H45.85M154.15 99.405H200" />
        </g>
      </g>
    </svg>
  );
}
